\begin{definition}[The combining map]
	\label{def:combine-map}
	\lean{MIPStarRE.QPBT.combinePoly, MIPStarRE.QPBT.combinePoly_eval}
	\lean{MIPStarRE.QPBT.combinePoly_mem_polyFunc}
	\lean{MIPStarRE.QPBT.combineLinePoly}
	\lean{MIPStarRE.QPBT.combineLinePolynomial_natDegree_le}
	\lean{MIPStarRE.QPBT.IsCombineLineCompatible, MIPStarRE.QPBT.combineLinePoly_spec}
	\leanok
	\uses{def:polyfunc, def:line, def:ideg-deg-polynomials}
	For $f, g \in \mathrm{ideg}_{d,m}(\F_q)$, the polynomial
	$\mathrm{combine}_{f,g} \in \mathrm{ideg}_{d,2m+2}(\F_q)$ is defined by
	\[
		\mathrm{combine}_{f,g}(x, z, \alpha, \beta)
		= \alpha f(x) + \beta g(z)\,,
		\qquad x \in \F_q^m,\ z \in \F_q^m,\ \alpha \in \F_q,\
		\beta \in \F_q\,.
	\]
	The combining map is also defined for polynomials restricted to lines.
	Let $\ell$ be a line in $\F_q^{2m+2}$ with intercept
	$u = (u_X, u_Z, u_\alpha, u_\beta)$ and slope
	$v = (v_X, v_Z, v_\alpha, v_\beta)$, and let $\ell_X$ and $\ell_Z$ be
	lines in $\F_q^m$ such that for every point
	$(x, z, \alpha, \beta) \in \ell$ it holds that $x \in \ell_X$ and
	$z \in \ell_Z$. Then for any two polynomials
	$f \in \deg_{md}(\ell_X)$ and $g \in \deg_{md}(\ell_Z)$, the polynomial
	$\mathrm{combine}_{f,g} \in \deg_{md+1}(\ell)$ is defined by
	\begin{equation}
		\label{eq:combine-lines}
		\mathrm{combine}_{f,g}(u + t \cdot v)
		= (u_\alpha + t \cdot v_\alpha)\, f(u_X + t \cdot v_X)
		+ (u_\beta + t \cdot v_\beta)\, g(u_Z + t \cdot v_Z)\,,
		\qquad t \in \F_q\,.
	\end{equation}
	The degree bound holds because $f$ and $g$, restricted to lines, are
	polynomials of degree at most $md$ in the line parameter, and each is
	multiplied by an affine factor of degree at most one.
\end{definition}

\begin{theorem}[Formalization support for Lemma~\ref{lem:qld-4-12}: averaged affine coarse-graining]
	\label{thm:qld-affine-coarse-graining}
	\lean{MIPStarRE.QPBT.opFamilyDistSq_uniform_affine_postprocess_le}
	\leanok
	\uses{def:povm-distance}
	This formalization-only auxiliary is not a named statement of the paper;
	it supplies the squared-distance estimate used in the coarse-graining
	step of Lemma~4.12 of \cite{Ji2020MIPStar}.
	Let $\F_q$ be a finite field, let $T$ be a finite nonempty set, and let
	$\ket\psi$ be a vector in a finite-dimensional complex Hilbert space
	$\hilb$. For each $t \in T$,
	let $\{A^t_{a,b}\}_{a,b \in \F_q}$ and $\{B^t_{a,b}\}_{a,b \in \F_q}$
	be operator families on $\hilb$ with equal total operators:
	$\sum_{a,b} A^t_{a,b} = \sum_{a,b} B^t_{a,b}$.
	For $\alpha,\beta,c \in \F_q$, set
	\[
		A^{t,\alpha,\beta}_c =
		\sum_{a,b\,:\,\alpha a+\beta b=c} A^t_{a,b},
		\qquad
		B^{t,\alpha,\beta}_c =
		\sum_{a,b\,:\,\alpha a+\beta b=c} B^t_{a,b}.
	\]
	Then, with all averages uniform and independent,
	\[
		\E_{t,\alpha,\beta} \sum_c
		\big\lVert (A^{t,\alpha,\beta}_c-B^{t,\alpha,\beta}_c)
		\ket\psi \big\rVert^2
		\le \E_t \sum_{a,b}
		\big\lVert (A^t_{a,b}-B^t_{a,b})\ket\psi \big\rVert^2.
	\]
\end{theorem}
\begin{proof}
	\leanok
	\uses{def:povm-distance}
	Fix $t$ and write $v_{a,b}=(A^t_{a,b}-B^t_{a,b})\ket\psi$.
	The equality of total operators gives $\sum_{a,b} v_{a,b}=0$.
	Two distinct pairs $(a,b)$ and $(a',b')$ satisfy
	$\alpha a+\beta b=\alpha a'+\beta b'$ with probability $1/q$ over
	uniform independent $\alpha,\beta$: the corresponding nonzero linear
	equation in two variables has $q$ solutions. Expanding squared norms
	in inner products therefore gives
	\[
		\E_{\alpha,\beta} \sum_c
		\Big\lVert \sum_{a,b\,:\,\alpha a+\beta b=c} v_{a,b} \Big\rVert^2
		= (1-q^{-1})\sum_{a,b}\lVert v_{a,b}\rVert^2
		+ q^{-1}\Big\lVert\sum_{a,b}v_{a,b}\Big\rVert^2
		\le \sum_{a,b}\lVert v_{a,b}\rVert^2.
	\]
	Averaging over $t$ proves the claim.
\end{proof}

